import RegistroUsuario from "../../../Componentes/Formularios/RegistroUsuario/RegistroUsuario";
import PestaniasConfiguraciones from "../../../Componentes/PestaniasConfiguraciones/PestaniasConfiguraciones";
import { useState, useEffect } from 'react';
import Boton from '../../../Componentes/Boton/Boton';
import Modal from '../../../Componentes/Modal/Modal';
import PlantillaConfiguraciones from '../../../Componentes/PlantillaConfiguraciones/PlantillaConfiguraciones';
import editar from '../../../assets/editar.png';
import mas from '../../../assets/mas.png';
import baja from '../../../assets/baja.png';
import alta from '../../../assets/alta.png';
import '../Proveedores/Proveedores.css';
import ModificarPermisos from "../../../Componentes/Formularios/Modificar Permisos/ModificarPermisos";
import { useValidarSesion } from "../../../hooks/useValidarSesion";
import { toast } from "sonner";

export default function Usuarios() {

    const { usuario, token } = useValidarSesion();

    const permisoCrearUsuario = usuario?.permisos?.some(
        (permiso) => permiso.nombrePermiso === 'crear usuario'
    ) ||
        usuario?.permisos_extra?.some(
            (permiso) => permiso.nombrePermiso === 'crear usuario'
        );

    const permisoModificarUsuario = usuario?.permisos?.some(
        (permiso) => permiso.nombrePermiso === 'modificar permisos'
    ) ||
        usuario?.permisos_extra?.some(
            (permiso) => permiso.nombrePermiso === 'modificar permisos'
        );

    ////////OBTENER LISTA DE USUARIOS
    const [usuarios, setUsuarios] = useState([]);
    const obtenerDatos = () => {
    fetch(`${import.meta.env.VITE_API_BASE_URL}/api/usuario`)
            .then(respuesta => respuesta.json())
            .then(datos => setUsuarios(datos))
            .catch(e => console.log(e));
    }

    useEffect(() => {
        obtenerDatos();
    }, []);
    console.log(usuarios);

    /////////MODAL NUEVO USUARIO
    const [modalNuevoUsuario, setModalNuevoUsuario] = useState(false);
    const manejaModalNuevoUsuario = () => {
        if (modalNuevoUsuario) {
            obtenerDatos();
        }
        setModalNuevoUsuario(!modalNuevoUsuario);
    };

    ////////MODAL MODIFICA USUARIO
    const [modalModificaUsuario, setModalModificaUsuario] = useState(false);
    const manejaModalModificaPermisosUsuario = () => {
        if (modalModificaUsuario) {
            obtenerDatos();
        }
        setModalModificaUsuario(!modalModificaUsuario);
    };

    //////MANEJA SELECCION
    const [seleccionado, setSeleccionado] = useState('');
    const manejaSeleccion = ({ id_usuario }) => {
        setSeleccionado({ id_usuario });
        manejaModalModificaPermisosUsuario();
    }

    //////MODAL PARA CONFIRMAR BAJA O REACTIVACION
    const [modalConfirmacionBaja, setModalConfirmacionBaja] = useState(false);
    const [datosConfirmacion, setDatosConfirmacion] = useState(null);

    const manejaModalConfirmacion = () => {
        setModalConfirmacionBaja(!modalConfirmacionBaja);
        if (modalConfirmacionBaja) {
            setDatosConfirmacion(null);
        }
    };

    //////ABRE MODAL PARA CONFIRMAR BAJA O REACTIVACION
    const manejarBajaOReactivacion = (id_usuario, usuarioNombre, estaActivo) => {
        setDatosConfirmacion({
            id_usuario,
            usuarioNombre,
            estaActivo
        });
        setModalConfirmacionBaja(true);
    };

    //////EJECUTA LA ACCION DE BAJA O REACTIVACION
    const ejecutarBajaOReactivacion = async () => {
        const { id_usuario, estaActivo } = datosConfirmacion;

        try {
            const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/usuario/${id_usuario}/baja`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({ activo: !estaActivo }) // Invierte el estado
            });

            if (!respuesta.ok) {
                const error = await respuesta.json();
                toast.error(error.error, { className: "__toaster_error" });
                return;
            }

            const mensajeExito = estaActivo 
                ? 'Usuario dado de baja correctamente' 
                : 'Usuario reactivado correctamente';
            toast.success(mensajeExito, { className: "__toaster_success" });
            obtenerDatos();
            manejaModalConfirmacion();
        } catch (error) {
            console.error('Error:', error);
            alert('Error al procesar la solicitud');
        }
    };

    /////////LAYOUT
    const navigation = <PestaniasConfiguraciones></PestaniasConfiguraciones>

    const main = <div className='__cuerpo_proveedores'>
        <div className='__cabecera_proveedores'>
            <h1>Usuarios</h1>
            {permisoCrearUsuario && <Boton icono={mas} habilitado onClick={manejaModalNuevoUsuario} title="Crear nuevo usuario"></Boton>}
        </div>
        <div className='__lista_proveedores'  >
            {usuarios.map((item, index) => (
                <div className="__proveedor_item" key={index} style={{
                    backgroundColor: item.activo ? 'transparent' : 'rgb(69 69 69 / 49%)'
                }}>
                    {permisoCrearUsuario ? <span style={{
                    
                    color: item.activo ? '#000' : 'white'
                }} className='__proveedor_categoria'>{`${item.apellido}, ${item.nombre} - Sucursal: ${item.sucursal?.nombre} - ${item.correo} ${!item.activo ? '(DADO DE BAJA)' : ''}`}</span> :
                        <span className='__proveedor_categoria' style={{ padding: "10px" }}>{`${item.apellido}, ${item.nombre} - Sucursal ${item.id_sucursal} - ${item.correo} ${!item.activo ? '(DADO DE BAJA)' : ''}`}</span>}
                    
                    <div style={{ display: 'flex', gap: '5px' }}>
                        {permisoModificarUsuario && (
                            <Boton 
                                habilitado={item.activo}
                                icono={editar} 
                                 title={item.activo ? "Modificar permisos" : "No se pueden modificar permisos de un usuario dado de baja"}
                                onClick={() => manejaSeleccion({ id_usuario: item.id_usuario })}
                            ></Boton>
                        )}
                        {permisoCrearUsuario && (
                            <Boton 
                                title={item.activo ? "Dar de baja al usuario" : "Reactivar usuario"}
                                habilitado 
                                onClick={() => manejarBajaOReactivacion(
                                    item.id_usuario, 
                                    `${item.apellido}, ${item.nombre}`,
                                    item.activo
                                )}
                                icono={item.activo ? baja : alta}
                            ></Boton>
                        )}
                    </div>
                </div>
            ))}
        </div>
        <Modal visible={modalNuevoUsuario} funcion={manejaModalNuevoUsuario} titulo="Nuevo Usuario" anchura="700px">
            <RegistroUsuario onGuardar={manejaModalNuevoUsuario}></RegistroUsuario>
        </Modal>
        <Modal visible={modalModificaUsuario} funcion={manejaModalModificaPermisosUsuario} titulo="Modificar Permisos" anchura="800px">
            <ModificarPermisos id_usuario={seleccionado.id_usuario} onGuardar={manejaModalModificaPermisosUsuario} token={token}></ModificarPermisos>
        </Modal>

        <Modal 
            visible={modalConfirmacionBaja} 
            funcion={manejaModalConfirmacion} 
            titulo={datosConfirmacion?.estaActivo ? "¿Dar de baja usuario?" : "¿Reactivar usuario?"} 
            anchura="500px"
        >
            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', marginBottom: '20px' }}>
                <p style={{ fontSize: '20px', color: '#333', fontFamily: 'sans-serif', textAlign: 'center' }}>
                    {datosConfirmacion?.estaActivo 
                        ? `¿Estás seguro de que deseas DAR DE BAJA a ${datosConfirmacion?.usuarioNombre}? Esta acción revocará sus credenciales.`
                        : `¿Estás seguro de que deseas REACTIVAR a ${datosConfirmacion?.usuarioNombre}? Podrá volver a acceder al sistema.`
                    }
                </p>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-around' }}>
                <Boton 
                    descripcion="CONFIRMAR"
                    onClick={ejecutarBajaOReactivacion} 
                    habilitado
                ></Boton>
                <Boton 
                    descripcion="CANCELAR" 
                    onClick={manejaModalConfirmacion} 
                    habilitado
                ></Boton>
            </div>
        </Modal>
    </div>

    return <PlantillaConfiguraciones navigation={navigation} main={main} />;
}