import { useForm } from "react-hook-form"
import Tarjeta from "../../ComponentesFormulario/Tarjeta/Tarjeta";
import Input from "../../Input/Input";
import Selector from "../../Selector/Selector";
import Boton from "../../Boton/Boton";
import React, { useState, useEffect } from 'react';
import './RegistroUsuario.css';
import iconMas from "../../../assets/mas.png";
import Modal from "../../Modal/Modal";
import NuevoRol from "../NuevoRol/NuevoRol";
import { toast } from "sonner";
import { useValidarSesion } from "../../../hooks/useValidarSesion";



export default function RegistroUsuario({ onGuardar }) {


    //Recupero informacion del usuario logueado
    const { token } = useValidarSesion(); // obtener el token desde Zustand

    const [modalNuevoRol, setModalNuevoRol] = useState(false); // Abre o cierra el modal nueva oferta

    const manejaModalNuevoRol = () => {
        setModalNuevoRol(!modalNuevoRol);
    };


    const { register, handleSubmit, formState: { errors }, reset } = useForm({
        //constante que devuleve todo lo del form

    });

    //////////// BUSCA SUCURSALES Y ROLES EN EL BACKEND
    const [sucursales, setSucursales] = useState([]);
    const [roles, setRoles] = useState([]);

    const obtenerDatos = () => {
    fetch(`${import.meta.env.VITE_API_BASE_URL}/api/sucursal`)
            .then(respuesta => respuesta.json())
            .then(datos => setSucursales(datos))
            .catch(e => console.log(e));
    fetch(`${import.meta.env.VITE_API_BASE_URL}/api/rol`)
            .then(respuesta => respuesta.json())
            .then(datos => setRoles(datos))
            .catch(e => console.log(e));
    };

    useEffect(() => {
        obtenerDatos();
    }, []);

    /////// REGISTRO USUARIO

    const onSubmit = async (data) => {
        console.log(data);
        setCargando(true);
        try {
            const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/usuario/registrar`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify(data),
            });

            // Intentamos leer siempre la respuesta (aunque haya error)
            const dataRespuestaUsuario = await respuesta.json().catch(() => ({}));

            if (respuesta.ok) {
                reset();
                toast.success("Usuario registrado correctamente.", { className: "__toaster_success" });
                onGuardar();
            } else {
                const mensajeError = dataRespuestaUsuario?.error || "Error al registrar el usuario.";
                toast.error(mensajeError, { className: "__toaster_error" });
                return;
            }
        } catch (error) {
            console.error('Error en la solicitud:', error);
            toast.error("Error inesperado al registrar el usuario.", { className: "__toaster_error" });
        } finally {
            setCargando(false);
        }
    };


    /////////// ESTADO PARA SABER CUANDO SE ESTA CARGANDO (SE ESTAN TRAYENDO LOS DATOS)
    const [cargando, setCargando] = useState(false);


    return (
        <>

            <form onSubmit={handleSubmit(onSubmit)} className="__formulario_nuevo_usuario">
                <div className="__cuerpo_nuevo_usuario">
                    <div className="__columna1">
                        <Tarjeta descripcion="Nombre" forid="nombre" mensajeError={errors.nombre?.message}>
                            <Input
                                tipo="text"
                                id="nombre"
                                {...register("nombre", { required: { value: true, message: "Ingrese nombre del empleado" } })}
                            />
                        </Tarjeta>
                        <Tarjeta descripcion="Correo" forid="correo" mensajeError={errors.correo?.message}>
                            <Input
                                tipo="text"
                                id="correo"
                                placeholder="example@gmail.com"
                                {...register("correo", {
                                    required: { value: true, message: "Ingrese Correo" },
                                    pattern: { value: /^[a-zA-Z0-9_.+-]+@[a-zA-Z0-9-]+\.[a-zA-Z]{2,4}$/, message: "Correo No Valido" }
                                })}
                            />
                        </Tarjeta>
                        <Tarjeta descripcion="Contraseña" forid="contraseña" mensajeError={errors.contraseña?.message}>
                            <Input
                                tipo="password"
                                id="contraseña"
                                {...register("contraseña", {
                                    required: { value: true, message: "Ingrese Contraseña" },
                                })}
                            />
                        </Tarjeta>
                        <Tarjeta descripcion="Fecha Nacimiento" forid="nacimiento" mensajeError={errors.nacimiento?.message}>
                            <Input
                                tipo="date"
                                id="nacimiento"
                                {...register("nacimiento", {
                                    required: { value: true, message: "Ingrese fecha de nacimiento" },
                                    validate: (value) => {
                                        const fechaNacimiento = new Date(value);
                                        const fechaActual = new Date();
                                        const edad = fechaActual.getFullYear() - fechaNacimiento.getFullYear();
                                        return edad >= 18 || "Debe ser mayor de edad";

                                    }
                                })}
                            />
                        </Tarjeta>
                    </div>
                    <div className="__columna2">
                        <Tarjeta descripcion="Apellido" forid="apellido" mensajeError={errors.apellido?.message}>
                            <Input
                                tipo="text"
                                id="apellido"
                                {...register("apellido", { required: { value: true, message: "Ingrese apellido del empleado" } })}
                            />
                        </Tarjeta>
                        <Tarjeta descripcion="Rol" forid="id_rol">
                            <Selector
                                opciones={roles.map(rol => ({ label: rol.nombre_rol, value: rol.id_rol }))}
                                {...register("id_rol")}
                            />
                        </Tarjeta>
                        <Tarjeta descripcion="Sucursal" forid="sucursal">
                            <Selector
                                opciones={sucursales.map(suc => ({ label: suc.nombre, value: suc.id_sucursal }))}
                                {...register("id_sucursal")}
                            />
                        </Tarjeta>
                        <Tarjeta descripcion="DNI" forid="dni" mensajeError={errors.dni?.message}>
                            <Input
                                tipo="text"
                                id="dni"
                                {...register("dni", { required: { value: true, message: "Ingrese DNI del empleado" } })}
                            />
                        </Tarjeta>
                    </div>
                    <div className="__columna3">
                        <Boton icono={iconMas} habilitado onClick={manejaModalNuevoRol}></Boton>
                    </div>

                </div>
                <div className="__boton_registro">
                    <Boton descripcion='Registrar' habilitado submit></Boton>
                </div>
                <div className="__modal_nuevo_proveedor">

                </div>
            </form>
            <Modal visible={modalNuevoRol} titulo="Nuevo Rol" funcion={manejaModalNuevoRol} anchura={"500px"} >
                <NuevoRol onGuardar={manejaModalNuevoRol}></NuevoRol>
            </Modal>
        </>

    )
}